CREATE TABLE auth_users(id BINARY(16) PRIMARY KEY,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'CUSTOMER',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT uq_auth_users_email UNIQUE(email));
